import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

swish_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void swish_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        float sigmoid_x = 1.0f / (1.0f + expf(-x));
        output[idx] = x * sigmoid_x;
    }
}

torch::Tensor swish_cuda(torch::Tensor input) {
    auto size = input.numel();
    auto output = torch::empty_like(input);

    const int blockSize = 256;
    const int gridSize = (size + blockSize - 1) / blockSize;

    swish_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size
    );

    return output;
}
"""

swish_cpp_source = r"""
torch::Tensor swish_cuda(torch::Tensor input);
"""

swish_module = load_inline(
    name="swish_module",
    cpp_sources=swish_cpp_source,
    cuda_sources=swish_source,
    functions=["swish_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)

mul_param_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mul_param_kernel(const float* x, const float* w, float* out,
                                 int batch_size, int out_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int size = batch_size * out_features;
    if (idx < size) {
        int col = idx % out_features;
        out[idx] = x[idx] * w[col];
    }
}

torch::Tensor mul_param_cuda(torch::Tensor x, torch::Tensor w) {
    auto batch_size = x.size(0);
    auto out_features = x.size(1);
    auto output = torch::empty_like(x);

    int size = batch_size * out_features;
    const int blockSize = 256;
    const int gridSize = (size + blockSize - 1) / blockSize;

    mul_param_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        out_features
    );

    return output;
}
"""

mul_param_cpp_source = r"""
torch::Tensor mul_param_cuda(torch::Tensor x, torch::Tensor w);
"""

mul_param_module = load_inline(
    name="mul_param_module",
    cpp_sources=mul_param_cpp_source,
    cuda_sources=mul_param_source,
    functions=["mul_param_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs a GEMM, GroupNorm, Swish, Multiply, and Swish operations
    with custom CUDA kernels for Swish and Multiply steps.
    """
    def __init__(self, in_features, out_features, num_groups, multiply_weight_shape):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.group_norm = nn.GroupNorm(num_groups, out_features)
        self.multiply_weight = nn.Parameter(torch.randn(multiply_weight_shape))

    def forward(self, x):
        x = self.gemm(x)
        x = self.group_norm(x)
        x = swish_module.swish_cuda(x)
        x = mul_param_module.mul_param_cuda(x, self.multiply_weight)
        x = swish_module.swish_cuda(x)
        return x
